/**
 * Collected docs must match their canonical source.
 *
 * `docs/addons/**` and `docs/frameworks/**` are generated by `docs:collect` from
 * `agentic/code/**\/docs/`. A section added only to a collected copy is silently
 * deleted by the next collect run, so `--check` fails when any collected doc
 * differs from what collection would write.
 *
 * @issue #4420
 */

import { describe, it, expect } from 'vitest';
import { spawnSync } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const COLLECTOR = path.join(ROOT, 'tools', 'manifest', 'collect-component-docs.mjs');

describe('docs:collect --check (#4420)', () => {
  it('reports no drift between collected docs and their sources', () => {
    const run = spawnSync(process.execPath, [COLLECTOR, '--check'], {
      cwd: ROOT,
      encoding: 'utf8',
      timeout: 120_000,
      killSignal: 'SIGKILL',
    });
    expect(run.error).toBeUndefined();
    expect(run.status, run.stderr).toBe(0);
    expect(run.stderr).not.toMatch(/differ from their source/);
  });
});
